def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    from functools import wraps

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                with (lock or nullcontext()):
                    result = cache[k]
            except KeyError:
                with (lock or nullcontext()):
                    result = func(*args, **kwargs)
                    cache[k] = result
            return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from collections import OrderedDict, namedtuple
    import weakref

    CacheInfo = namedtuple('CacheInfo', ['hits', 'misses'])

    class _TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.cache = OrderedDict()
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.__cacheinfo__((0, 0))

        def __getitem__(self, key):
            try:
                record = self.cache[key]
            except KeyError:
                self.__cacheinfo__.misses += 1
                return self.__missing__(key)
            else:
                value, expiration_time = record.value, record.expiration_time
                if expiration_time <= self.timer():
                    self.__cacheinfo__.misses += 1
                    del self.cache[key]
                    return self.__missing__(key)
                else:
                    self.__cacheinfo__.hits += 1
                    return value

        def __setitem__(self, key, value):
            if key not in self.cache or self.cache[key].expiration_time <= self.timer():
                if self.maxsize == 0:
                    return
                if self.typed or isinstance(key, tuple):
                    self.cache[key] = _CacheItem(value, self.timer() + self.ttl)
                else:
                    self.cache[key] = _CacheItem(value, self.timer() + self.ttl)
                    while len(self.cache) > self.maxsize:
                        self.cache.popitem(last=False)
            else:
                self.cache.move_to_end(key)
                self.__setitem__(key, value)

        def __missing__(self, key):
            return self._make_delegated_function()(key)

        def __make_delegated_function__(self):
            self.cache_clear()
            return self.func

        def __cacheinfo__(self, info=None):
            if info is not None:
                self.__cache_hits = info.hits
                self.__cache_misses = info.misses
            else:
                return CacheInfo(self.__cache_hits, self.__cache_misses)

        def cache_clear(self):
            self.cache.clear()
            self.__cacheinfo__((0, 0))

    def wrapper(func):
        wrapper.cache_clear = _TTLCache.cache_clear.__get__(wrapper.cache)
        wrapper.cache_info = _TTLCache.__cacheinfo__.__get__(wrapper.cache)
        wrapper.__cache_bits = maxsize.__hash__() & (2**32 - 1) | (typed.__hash__() & 2**31)
        wrapper.func = func
        return wrapper

    wrapper.cache = _TTLCache(maxsize, ttl, timer, typed)
    return wrapper

