def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    from collections import OrderedDict, Counter

    def decorator(func):
        func.cache_info = lambda: cache.info()
        func.cache_clear = cache.cache_clear
        func.cache_dump = cache.cache_dump

        cache = {
            'cache': OrderedDict(),
            'access_count': Counter(),
            'maxsize': maxsize,
            'typed': typed
        }

        def wrapped_func(*args, **kwargs):
            key = (func, args, tuple(kwargs.items()))
            if typed:
                key = (type(key), key)
            try:
                access_count = cache['access_count'][key]
            except KeyError:
                access_count = 0

            cache['access_count'][key] = access_count + 1

            if key not in cache['cache']:
                if len(cache['cache']) >= cache['maxsize']:
                    least_frequent_key = min(cache['access_count'], key=cache['access_count'].get)
                    del cache['cache'][least_frequent_key]
                    del cache['access_count'][least_frequent_key]
                cache['cache'][key] = func(*args, **kwargs)

            return cache['cache'][key]

        return wrapped_func

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('popitem from empty dictionary')
    key, value = next(iter(self.items()))
    del self[key]
    return (key, value)

