def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a set of all base classes, ensuring uniqueness
    classes = set(classes)

    # Function to determine if a class can be removed
    def can_remove(cls, remaining_classes):
        # Check if the class is a subclass of any remaining class
        return any(issubclass(cls, other) for other in remaining_classes if other != cls)

    # Remove classes that are subclasses of others
    while True:
        changed = False
        for cls in list(classes):
            if can_remove(cls, classes):
                classes.remove(cls)
                changed = True
        if not changed:
            break

    # Sort the classes by their diamond configuration (MDM)
    def depends_on(cls, remaining_classes):
        return any(issubclass(sub, cls) for sub in remaining_classes if sub != cls)

    while True:
        changed = False
        for i in range(len(classes)):
            for j in range(i + 1, len(classes)):
                a, b = classes[i], classes[j]
                if depends_on(a, classes) and depends_on(b, classes):
                    if depends_on(a, [b]):
                        classes.add(a)
                        classes.remove(b)
                        changed = True
                    elif depends_on(b, [a]):
                        classes.add(b)
                        classes.remove(a)
                        changed = True
        if not changed:
            break

    return sorted(classes, key=lambda cls: (issubclass(cls, Node), classes.index(cls)))

