def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr[0] == '&':
            if expr[1][0] == '~':
                if expr[1][1] == expr[0][1]:
                    result.append(expr[2])
                else:
                    result.append(expr)
            elif expr[2][0] == expr[0][1]:
                result.append(expr[0])
            else:
                result.append(expr)
        elif expr[0] == '|':
            if expr[1][0] == '~':
                if expr[1][1] == expr[0][1]:
                    result.append(expr[2])
                else:
                    result.append(expr)
            elif expr[2][0] == expr[0][1]:
                result.append(expr[0])
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        if sys.version_info[0] == 2:
            return [n.encode('utf-8') if isinstance(n, unicode) else n for n in namefunc()]
        else:
            return namefunc()
    except Exception as e:
        raise Exception("Error converting timezone names: " + str(e))

