def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    nums = [int(n) for n in version.split('.')]
    for i in range(len(nums)-1, -1, -1):
        nums[i] += 1
        if nums[i] < 10:
            nums[i] = str(nums[i]).zfill(2)
            break
        nums[i] = '00'
    else:
        nums.insert(0, '00')
    return '.'.join(nums)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    root_inventory = self.get_inventory('root')
    if not root_inventory:
        raise ValueError("Root inventory not found")

    content_digests = {}

    for version_dir in version_dirs:
        inventory = self.get_inventory(version_dir)
        if not inventory:
            raise ValueError(f"Inventory not found for version {version_dir}")

        for file in inventory.files:
            if file.digest != root_inventory.get_file(file.name).digest:
                content_digests[file.name] = file.digest

    self.content_digests = content_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, list):
        raise TypeError("bug_ids must be a list")

    for bug_id in bug_ids:
        if not isinstance(bug_id, int):
            raise ValueError("All elements of bug_ids must be integers")

    params['ids'] = bug_ids
    return params

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """

    merged = {}
    for key, value in nodes:
        if key.value not in merged:
            merged[key.value] = value
        elif isinstance(value, ruamel.yaml.nodes.MappingNode):
            if not isinstance(merged[key.value], ruamel.yaml.nodes.MappingNode):
                # Replace non-mapping value with the current mapping
                merged[key.value] = value
            else:
                merged_items = dict(merged[key.value].value)
                for item_key, item_value in value.value:
                    if isinstance(item_value, ruamel.yaml.nodes.MappingNode):
                        if item_key.value in merged_items and isinstance(merged_items[item_key.value], ruamel.yaml.nodes.MappingNode):
                            merged_items[item_key.value] = deep_merge_nodes([(item_key.value, item_value)])
                        else:
                            merged_items[item_key.value] = item_value
                    else:
                        merged_items[item_key.value] = item_value
                merged[key.value] = ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=list(merged_items.items()))

    return [(key, merged[key]) for key in merged.keys()]

def parser_flags(parser):
    ''' Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string. '''
    flags = set()
    for action in parser._actions:
        for option_string in action.option_strings:
            flags.add(option_string)
    # Join the flags with spaces and return
    return ' '.join(sorted(flags))

def deep_merge_nodes(nodes):
    result = {}
    for key_node, value_node in nodes:
        if key_node.value in result:
            if isinstance(result[key_node.value], ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                sub_result = {}
                for sub_key_node, sub_value_node in value_node.value:
                    sub_result[sub_key_node.value] = sub_value_node
                merged_value = deep_merge_nodes([ (ScalarNode(tag='tag:yaml.org,2002:str', value=sub_key_node.value), sub_result[sub_key_node.value]) for sub_key_node in sub_result ])
                result[key_node.value] = MappingNode(tag='tag:yaml.org,2002:map', value=[ (ScalarNode(tag='tag:yaml.org,2002:str', value=sub_key_node.value), sub_merged_value) for sub_key_node, sub_merged_value in merged_value ])
            else:
                result[key_node.value] = value_node
        else:
            result[key_node.value] = value_node
    return [(key_node, value_node) for key_node, value_node in result.items()]

