def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:
        regex = r'([^\w/\\;:`"=\x20]+)'  # POSIX
    elif platform == 0:
        regex = r'([^\w:\\/;:`"=\x20]+)'  # Windows/CMD
    else:
        raise ValueError("Invalid platform value")

    return re.split(regex, s)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not Path(archive_path).exists():
        raise FileNotFoundError(f"Archive path {archive_path} does not exist")

    if not Path(tmp_path).exists():
        raise FileNotFoundError(f"Temporary path {tmp_path} does not exist")

    if not filename:
        filename = Path(archive_path).name

    temp_dir = Path(tmp_path) / filename.replace(".tar.gz", "")
    temp_dir.mkdir(parents=True, exist_ok=True)

    subprocess.run(["tar", "-xzf", archive_path, "-C", str(temp_dir)])

    return str(temp_dir)

def parse_frequency(frequency):
    '''Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency.lower() == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    number, unit = parts
    number = float(number)

    delta_args = {
        'days': 0,
        'seconds': 0,
        'microseconds': 0,
        'milliseconds': 0,
        'minutes': 0,
        'hours': 0,
        'weeks': 0
    }

    if unit.endswith('s'):
        unit = unit[:-1]

    if unit in delta_args:
        delta_args[unit] = number
        return datetime.timedelta(**delta_args)
    else:
        raise ValueError(f"Invalid time unit: {unit}")

