def make_find_paths(find_paths):
    transformed_paths = []
    for path in find_paths:
        if re.match(r'.*[*?[]', path):
            # path is already a pattern
            transformed_paths.append(path)
        else:
            # escape the path and convert to glob pattern
            escaped_path = path.replace('?', '\?').replace('*', '\*').replace('[', '\[').replace(']', '\]')
            transformed_paths.append(f'sh:**/*{escaped_path}*/**')
    return transformed_paths

