def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration, and sequence of logging.LogRecord instances containing any parse errors.'''

    import json
    from io import StringIO
    import logging
    import os

    config_dict = {}
    log_records = []
    logger = logging.getLogger(__name__)

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as f:
                config = json.load(f)

                if resolve_env:
                    for key, value in config.items():
                        if isinstance(value, str) and value.startswith('$'):
                            try:
                                config[key] = os.environ[value[1:]]
                            except KeyError:
                                logger.error(f"Environment variable {value[1:]} not found in {config_filename}")
                                log_records.append(logging.LogRecord('config_loader', logging.ERROR, config_filename, 0, f"Environment variable {value[1:]} not found", (), exc_info=None))

                config_dict[config_filename] = config

        except FileNotFoundError:
            logger.error(f"Configuration file {config_filename} not found")
            log_records.append(logging.LogRecord('config_loader', logging.ERROR, config_filename, 0, f"Configuration file {config_filename} not found", (), exc_info=None))
        except json.JSONDecodeError:
            logger.error(f"Failed to decode JSON from {config_filename}")
            log_records.append(logging.LogRecord('config_loader', logging.ERROR, config_filename, 0, f"Failed to decode JSON from {config_filename}", (), exc_info=None))
        except Exception as e:
            logger.error(f"An unexpected error occurred while loading {config_filename}: {str(e)}")
            log_records.append(logging.LogRecord('config_loader', logging.ERROR, config_filename, 0, f"An unexpected error occurred while loading {config_filename}: {str(e)}", (), exc_info=None))

    return config_dict, log_records

