def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        if other is None:
            return self._scale

        if isinstance(other, (int, float)) and other > 0:
            if self._scale == 0:
                raise LenaValueError("Cannot rescale graph with unknown or zero scale.")
            self._scale = other
            for field in self._data:
                if field['scale'] == self._scale:
                    field['scale'] = other
            for error in self._errors:
                if error['scale'] == self._scale:
                    error['scale'] = other
            self._scale = other
        else:
            raise ValueError("Invalid input for rescaling. Must be a positive number or None.")

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""

    if not tentative:
        for item in iface.methods:
            if not hasattr(candidate, item):
                return False

    for item in iface.properties:
        if not hasattr(candidate, item):
            return False

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check for an explicit metaclass
    if explicit_mc is not None:
        return explicit_mc

    # Find the metaclass in the bases if available
    for base in bases:
        if inspect.isclass(base):
            metaclass = getattr(base, '__metaclass__', None)
            if metaclass is not None:
                return metaclass

    # Default to type if no metaclass is found
    return type

def pop(self, key, default=__marker):
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:
        if default is __marker:
            raise
        return default

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""

    try:
        key = min(self._counter, key=self._counter.get)
        value = self[key]
        del self[key]
        del self._counter[key]
        return (key, value)
    except ValueError:
        raise KeyError("popitem(): dictionary is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""

    if not self._data:
        raise KeyError("popitem(): dictionary is empty")

    key = next(iter(self._data))
    return key, self._data.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""

    try:
        return self.cache.popitem()
    except KeyError:
        raise KeyError("popitem from an empty FoliadbDict")

