def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    from typing import Set, Tuple

    tags = set()
    code_block_pattern = re.compile(r'(```[\s\S]*?```|`[^`]*`)')
    in_code_block = False

    def replace_tag(tag):
        if replacer:
            return replacer(tag.group(0))
        return tag.group(0)

    def find_tags_in_segment(segment):
        nonlocal in_code_block
        tag_pattern = re.compile(r'<([a-zA-Z0-9_]+)>')
        result = []
        last_end = 0
        for match in tag_pattern.finditer(segment):
            if not in_code_block:
                result.append(segment[last_end:match.start()])
                result.append(replace_tag(match))
                tags.add(match.group(1))
                last_end = match.end()
            elif match.group(0).startswith('```'):
                in_code_block = not in_code_block
        result.append(segment[last_end:])
        return ''.join(result)

    for code_segment in code_block_pattern.split(text):
        if code_segment.startswith('```'):
            in_code_block = not in_code_block
        else:
            text = find_tags_in_segment(code_segment)

    return tags, text

