def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    children_dict = {}
    for child in node:
        tag = child.tag
        if tag not in children_dict:
            children_dict[tag] = [child]
        else:
            children_dict[tag].append(child)
    return children_dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    Parameters:
        document (str): The webfinger document as a string.

    Returns:
        Dict: The parsed webfinger data.

    Raises:
        Exception: If the document is neither valid JSON nor XRD.
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            # Try to parse as XRD
            root = ET.fromstring(document)
            data = {}
            for elem in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd/1.0}Link'):
                data[elem.get('rel')] = elem.get('href')
            return data
        except ET.ParseError:
            raise Exception("Invalid webfinger document. Neither valid JSON nor XRD.")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    url = f"https://{handle}.well-known/webfinger"
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()
    except (requests.RequestException, ValueError):
        return None

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, params=data, timeout=timeout, *args, **kwargs)
        else:
            raise ValueError("Unsupported method: {}".format(method))

        return response.status_code, None
    except Exception as e:
        return None, e

def dict_insert(dic, val, key, *keys):
    if not keys:
        dic[key] = val
    else:
        if key not in dic:
            dic[key] = {}
        dict_insert(dic[key], val, *keys)

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type

    Parameters:
        settings_dirs (list): A list of directory paths
        spec_option (str): A specification option

    Returns:
        list: A list of file names
    """
    try:
        file_names = []
        for directory in settings_dirs:
            if os.path.exists(directory):
                for root, _, files in os.walk(directory):
                    for file in files:
                        if spec_option in file:
                            file_names.append(os.path.join(root, file))
        return file_names
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

