def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """

    # Check if the command_name is valid
    if not self.commands:
        return None

    command = self.commands.get(command_name)
    if not command:
        return None

    # Check if the argument_name is valid for the command
    if argument_name not in command.arguments:
        return None

    return command.arguments[argument_name]

