def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    if not args:
        raise ValueError("No arguments provided")

    for arg in args:
        if not isinstance(arg, (int, float)):
            raise ValueError("All arguments must be numbers")

        if len(arg) != 2 or not all(isinstance(x, (int, float)) for x in arg):
            raise ValueError("Each argument must be a tuple of two numbers")

        min_val, max_val = arg
        if min_val > max_val:
            raise ValueError("Minimum value must be less than or equal to maximum value")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg[len('--control-'):]] = True
        elif arg.startswith('--nested-'):
            nested_args[arg[len('--nested-'):]] = True
        elif arg.startswith('--custom-'):
            custom_args[arg[len('--custom-'):]] = True
        else:
            nested_args[arg] = True

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """

    if extra_vars is None:
        extra_vars = {}

    for key, value in extra_vars.items():
        if key in vars_dict:
            if isinstance(vars_dict[key], list) and isinstance(value, list):
                vars_dict[key].extend(value)
            elif isinstance(vars_dict[key], dict) and isinstance(value, dict):
                vars_dict[key].update(value)
            else:
                vars_dict[key] = value
        else:
            vars_dict[key] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    type_casters = {
        'int': int,
        'float': float,
        'bool': lambda s: s.lower() in ['true', '1', 't', 'y', 'yes'],
    }

    for key, value in values_dict.items():
        if value in ['None', 'none', 'nil', 'NaN', 'True', 'False']:
            values_dict[key] = None if value.lower() in ['none', 'nil'] else value.lower() in ['true', '1', 't', 'y', 'yes']
        else:
            for converter_type, converter in type_casters.items():
                try:
                    values_dict[key] = converter(value)
                    break
                except ValueError:
                    continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    from json import load

    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        with open(spec_path, 'r') as f:
            plugin_spec = load(f)

        flat_dict = {}
        for key, value in plugin_spec.items():
            if isinstance(value, dict):
                flat_dict.update({f'{key}_{k}': v for k, v in value.items()})
            else:
                flat_dict[key] = value

        return flat_dict
    except FileNotFoundError:
        raise FileNotFoundError(f'Plugin spec file not found at {spec_path}')
    except JSONDecodeError:
        raise ValueError(f'Invalid JSON content in plugin spec file at {spec_path}')

